package vn.com.apartment.billing;
import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import vn.com.apartment.resident.Customer;
@Service public class PaymentNotificationService{
 private final PaymentNotificationRepository repository;private final String telegramToken,zaloToken;
 public PaymentNotificationService(PaymentNotificationRepository repository,@Value("${app.messaging.telegram-bot-token:}") String telegramToken,@Value("${app.messaging.zalo-oa-access-token:}") String zaloToken){this.repository=repository;this.telegramToken=telegramToken;this.zaloToken=zaloToken;}
 public PaymentNotification send(PaymentQrRequest qr,Customer customer,String requestedChannel,String qrImageUrl){String channel;try{channel=choose(customer,requestedChannel);}catch(Exception e){channel=requestedChannel==null?"AUTO":requestedChannel.toUpperCase();PaymentNotification failed=repository.save(new PaymentNotification(qr,customer,channel,"NOT_CONFIGURED"));failed.failed(e.getMessage());return failed;}String recipient="TELEGRAM".equals(channel)?customer.getTelegramChatId():customer.getZaloUserId();PaymentNotification log=repository.save(new PaymentNotification(qr,customer,channel,recipient));String services=qr.getAllocations().stream().map(a->a.getReceivableItem().getDescription()).reduce((a,b)->a+", "+b).orElse("Dịch vụ");String caption="Thông báo phí căn "+qr.getReceivable().getUnit().getCode()+"\nDịch vụ: "+services+"\nSố tiền: "+qr.getAmount().toPlainString()+" VND\nNội dung CK: "+qr.getReferenceCode();try{if("TELEGRAM".equals(channel))sendTelegram(recipient,qrImageUrl,caption);else sendZalo(recipient,caption+"\nQR: "+qrImageUrl);log.sent();}catch(Exception e){log.failed(e.getMessage());}return log;}
 private String choose(Customer c,String requested){String channel=requested==null?"AUTO":requested.toUpperCase();if("TELEGRAM".equals(channel)&&has(c.getTelegramChatId()))return channel;if("ZALO".equals(channel)&&has(c.getZaloUserId()))return channel;if("AUTO".equals(channel)){if(has(c.getZaloUserId()))return "ZALO";if(has(c.getTelegramChatId()))return "TELEGRAM";}throw new IllegalArgumentException("Chủ hộ chưa có "+("AUTO".equals(channel)?"Zalo user ID hoặc Telegram chat ID":channel+" ID")+".");}
 private void sendTelegram(String chatId,String photo,String caption){if(!has(telegramToken))throw new IllegalStateException("Chưa cấu hình TELEGRAM_BOT_TOKEN.");Map result=RestClient.create().post().uri("https://api.telegram.org/bot"+telegramToken+"/sendPhoto").contentType(MediaType.APPLICATION_JSON).body(Map.of("chat_id",chatId,"photo",photo,"caption",caption)).retrieve().body(Map.class);if(result==null||!Boolean.TRUE.equals(result.get("ok")))throw new IllegalStateException("Telegram từ chối gửi tin.");}
 private void sendZalo(String userId,String text){if(!has(zaloToken))throw new IllegalStateException("Chưa cấu hình ZALO_OA_ACCESS_TOKEN.");Map result=RestClient.create().post().uri("https://openapi.zalo.me/v3.0/oa/message/cs").header("access_token",zaloToken).contentType(MediaType.APPLICATION_JSON).body(Map.of("recipient",Map.of("user_id",userId),"message",Map.of("text",text))).retrieve().body(Map.class);if(result==null||!"0".equals(String.valueOf(result.getOrDefault("error","-1"))))throw new IllegalStateException("Zalo từ chối gửi tin: "+(result==null?"không có phản hồi":result.get("message")));}
 private boolean has(String value){return value!=null&&!value.isBlank();}
}
